  function updateCastform(pokemon, weather, player) {
    let weatherForm = "CASTFORM" /* CASTFORM */;
    if (weather === "SNOW" /* SNOW */) {
      weatherForm = "CASTFORM_HAIL" /* CASTFORM_HAIL */;
    } else if (weather === "RAIN" /* RAIN */) {
      weatherForm = "CASTFORM_RAIN" /* CASTFORM_RAIN */;
    } else if (weather === "SUN" /* SUN */) {
      weatherForm = "CASTFORM_SUN" /* CASTFORM_SUN */;
    }
    if (pokemon.name === weatherForm) return;
    if (!player) return;
    const newPokemon = PokemonFactory.createPokemonFromName(weatherForm, player);
    pokemon.items.forEach((item) => {
      newPokemon.items.add(item);
    });
    newPokemon.positionX = pokemon.positionX;
    newPokemon.positionY = pokemon.positionY;
    player.board.delete(pokemon.id);
    player.board.set(newPokemon.id, newPokemon);
    player.updateSynergies();
  }
